<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE']);$db=Database::connection();$id=max(0,(int)($_GET['id']??$_POST['id']??0));$d=['code'=>'','libelle'=>'','description'=>''];$error='';if($id){$s=$db->prepare('SELECT * FROM garanties WHERE id=?');$s->execute([$id]);$d=$s->fetch()?:exit('Garantie introuvable.');}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach(array_keys($d) as $f)$d[$f]=trim((string)($_POST[$f]??''));if($d['code']===''||$d['libelle']==='')$error='Le code et le libellé sont obligatoires.';else{try{if($id)$db->prepare('UPDATE garanties SET code=?,libelle=?,description=? WHERE id=?')->execute([strtoupper($d['code']),$d['libelle'],$d['description']?:null,$id]);else{$db->prepare('INSERT INTO garanties(code,libelle,description) VALUES(?,?,?)')->execute([strtoupper($d['code']),$d['libelle'],$d['description']?:null]);$id=(int)$db->lastInsertId();}audit('ENREGISTREMENT','garantie',$id);flash('success','Garantie enregistrée.');redirect('garanties/index.php');}catch(PDOException){$error='Ce code existe déjà.';}}}$title=$id?'Modifier la garantie':'Nouvelle garantie';require __DIR__.'/../../includes/header.php';?>
<div class="form-shell"><div class="page-heading"><h1 class="h3"><?= e($title) ?></h1><a class="btn btn-outline-secondary" href="index.php">Retour</a></div><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post" class="card card-body"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $id ?>"><div class="row g-3"><div class="col-md-4"><label class="form-label">Code *</label><input class="form-control" name="code" value="<?= e($d['code']) ?>" required></div><div class="col-md-8"><label class="form-label">Libellé *</label><input class="form-control" name="libelle" value="<?= e($d['libelle']) ?>" required></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" rows="4" name="description"><?= e($d['description']) ?></textarea></div></div><div class="text-end mt-4"><button class="btn btn-primary">Enregistrer</button></div></form></div><?php require __DIR__.'/../../includes/footer.php'; ?>
